S = "Hakeem Force Academy"
QS = [
 (S, "Who, as Viceroy of India, introduced separate electorates for Muslims through the reforms of 1909?", ["Lord Curzon", "Lord Minto", "Lord Ripon", "Lord Mountbatten"], 1,
  "Lord Minto was Viceroy in 1909 and, with Secretary of State Lord Morley, brought the Morley-Minto Reforms that gave Muslims separate electorates. The demand had been made by the Simla Deputation of 1906.",
  "Because of this, Lord Minto is often called the Father of Communal Electorates.", [4152]),
 (S, "What is the meaning of the idiom \"to hit the nail on the head\"?", ["To do something very slowly", "To say or do exactly the right thing", "To make a big mistake", "To hurt oneself"], 1,
  "The idiom means to describe a problem or give an answer that is exactly right. The usual form is \"hit the nail on the head\".",
  "An idiom is a phrase whose meaning is different from the meanings of its separate words.", [3017]),
 (S, "Who was the first Pakistani cricketer to score a triple century in Test cricket?", ["Inzamam-ul-Haq", "Younis Khan", "Hanif Mohammad", "Javed Miandad"], 2,
  "Hanif Mohammad scored 337 against the West Indies at Bridgetown in 1958. It was the first Test triple century by a Pakistani.",
  "Hanif also scored 499 for Karachi in 1958-59, which was then the highest first-class score.", [1244]),
 (S, "How many Pakistanis have won a Nobel Prize?", ["1", "2", "3", "4"], 1,
  "Dr Abdus Salam won the Nobel Prize in Physics in 1979 and Malala Yousafzai won the Nobel Peace Prize in 2014. No other Pakistani national has won as of 2026.",
  "Abdus Salam was the first Pakistani and the first Muslim from Pakistan to win a Nobel Prize.", [388]),
 (S, "What does the idiom \"to pick holes\" mean?", ["To dig the ground", "To find faults and criticise", "To repair something", "To praise someone highly"], 1,
  "To pick holes in something means to look for its weak points and criticise it.",
  "A similar phrase is \"to find fault with\".", [2539, 3018]),
 (S, "Fill in the blank with the correct preposition: We are pinning all our hopes ___ the new manager.", ["at", "with", "on", "to"], 2,
  "The correct phrase is \"pin hopes on someone\", meaning to depend on that person for success.",
  "The same preposition is used in \"pin the blame on someone\".", [1560, 1586]),
 (S, "Fill in the blank: As I was hot, I ___ my coat.", ["took off", "put on", "took in", "put off"], 0,
  "Being hot, a person would remove the coat, and the phrasal verb for removing clothes is \"took off\". The past tense is needed because of \"was\".",
  "The opposite phrasal verb is \"put on\".", [1416]),
 (S, "Which place in Pakistan is famous for its natural hot springs?", ["Murree", "Tatta Pani", "Naran", "Ziarat"], 1,
  "Tatta Pani in Kotli district of Azad Kashmir is well known for its hot water springs. Its name means hot water in Urdu.",
  "Tatta Pani is also the name of another hot spring site near Gilgit-Baltistan.", [3656]),
 (S, "Which is the hottest desert in the world?", ["Gobi Desert", "Thar Desert", "Sahara Desert", "Arabian Desert"], 2,
  "The Sahara in Africa is the largest hot desert and is generally called the hottest desert of the world.",
  "The Sahara covers about 9 million square kilometres of North Africa.", [2915]),
 (S, "According to the Holy Quran, for what purpose did Allah divide mankind into nations and tribes?", ["So that they may fight each other", "So that they may know one another", "So that some may rule others", "So that they may trade"], 1,
  "Surah Al-Hujurat (49:13) says Allah made people into nations and tribes so that they may know one another.",
  "The same verse says the most honoured before Allah is the one who is most righteous.", [1356]),
 (S, "Which gas in the air is essential for human breathing?", ["Nitrogen", "Carbon dioxide", "Oxygen", "Hydrogen"], 2,
  "Humans need oxygen for respiration, which releases energy from food in the body cells.",
  "Oxygen makes up about 21 percent of the air.", [3752]),
 (S, "Which country hosted the first ICC Cricket World Cup in 1975?", ["Australia", "India", "West Indies", "England"], 3,
  "The first Cricket World Cup was played in England in June 1975 with 60-over matches.",
  "England also hosted the 1979, 1983 and 1999 editions and the 2019 edition.", [4147]),
 (S, "Which team won the first ICC Cricket World Cup in 1975?", ["Australia", "West Indies", "England", "Pakistan"], 1,
  "West Indies beat Australia in the 1975 final at Lord's, led by Clive Lloyd.",
  "West Indies also won the second World Cup in 1979.", [4430]),
 (S, "Identify the tense of the sentence: They are playing cricket.", ["Present simple", "Present continuous", "Present perfect", "Future continuous"], 1,
  "The sentence uses \"are\" with the verb ending in -ing, which is the form of the present continuous tense.",
  "Present continuous is used for actions happening now.", [1844]),
 (S, "What is an identity matrix?", ["A square matrix with all elements zero", "A square matrix with 1 on the main diagonal and 0 elsewhere", "A matrix with only one row", "A matrix with all elements equal to 1"], 1,
  "An identity matrix is a square matrix whose main diagonal elements are all 1 and all other elements are 0.",
  "Multiplying any matrix by the identity matrix of a suitable size leaves it unchanged.", [910]),
 (S, "What is the determinant of an identity matrix?", ["0", "1", "-1", "Equal to its order"], 1,
  "The determinant of a diagonal matrix is the product of its diagonal elements. For an identity matrix this is 1 x 1 x ... x 1 = 1.",
  "The identity matrix is its own inverse.", [2876]),
 (S, "What does the idiom \"out and out\" mean?", ["Completely or thorough", "Outside the house", "Slightly", "Never"], 0,
  "\"Out and out\" means complete or total, as in \"an out and out liar\".",
  "It is used before a noun to stress that something is complete.", [3013]),
 (S, "What does the idiom \"to cry wolf\" mean?", ["To be very sad", "To raise a false alarm", "To hunt animals", "To ask for help bravely"], 1,
  "To cry wolf is to give a false warning so that people do not believe you when real danger comes.",
  "The idiom comes from Aesop's fable The Boy Who Cried Wolf.", [3016]),
 (S, "How many ayat (verses) does Surah Al-Ikhlas have?", ["3", "4", "5", "6"], 1,
  "Surah Al-Ikhlas (112) has 4 ayat. It describes the oneness of Allah.",
  "Reciting it is said to equal one third of the Quran in reward.", [177, 183]),
 (S, "Which river is regarded as the most important river of Pakistan?", ["Jhelum", "Indus", "Ravi", "Chenab"], 1,
  "The Indus is the longest river of Pakistan and the main source of water for its agriculture and for the country's irrigation system.",
  "The Indus flows from Tibet through Pakistan to the Arabian Sea.", [3998]),
 (S, "What is the main purpose of zakat in Islam?", ["To increase the wealth of the rich", "To reduce poverty and help the needy", "To pay government taxes", "To build mosques only"], 1,
  "Zakat is a compulsory share of wealth given to the poor and needy, which reduces the gap between rich and poor.",
  "Zakat is the third pillar of Islam and is 2.5 percent on savings above nisab.", [4466]),
 (S, "What is the antonym of \"impoverished\"?", ["Poor", "Wealthy", "Weak", "Hungry"], 1,
  "Impoverished means made poor, so its opposite is wealthy or rich.",
  "Affluent is another antonym of impoverished.", [463]),
 (S, "What is the synonym of \"impoverished\"?", ["Rich", "Generous", "Destitute", "Healthy"], 2,
  "Impoverished means very poor, and destitute has the same meaning.",
  "Needy and penniless are also synonyms.", [3185]),
 (S, "In which province of Pakistan was the Sui gas field discovered and developed?", ["Punjab", "Sindh", "Balochistan", "Khyber Pakhtunkhwa"], 2,
  "Sui is in the Dera Bugti district of Balochistan, and its gas field began supplying the country in the 1950s.",
  "Sui is the largest natural gas field of Pakistan.", [2096]),
 (S, "Which famous event took place in 8 Hijri?", ["Battle of Badr", "Treaty of Hudaibiya", "Conquest of Makkah", "Farewell Hajj"], 2,
  "The Muslims conquered Makkah peacefully in Ramadan 8 AH.",
  "Battle of Hunain and the Battle of Muta also took place in 8 AH.", [1139]),
]
